<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {request} from './api'
import AdminIcon from './components/AdminIcon.vue'
import {initialContent} from './cms'
type Data=Record<string,any>
const me=ref<Data|null>(null),tab=ref('registrations'),busy=ref(false),error=ref(''),notice=ref(''),initialized=ref(true)
const rows=ref<Data[]>([]),total=ref(0),page=ref(0),q=ref(''),status=ref(''),source=ref(''),campaign=ref('')
const config=ref<Data>({}),content=ref<Data>(initialContent()),contentVersion=ref(0),templates=ref<Data[]>([]),preview=ref<Data|null>(null),stats=ref<Data>({}),roles=ref<Data[]>([]),principal=ref(''),role=ref('manager'),retention=ref<Data|null>(null)
const overview=ref<Data>({}),menuOpen=ref(false),contentPanel=ref('texts'),textGroup=ref('hero')
const statusNames:Record<string,string>={pending:'Ожидает',approved:'Подтверждена',waitlisted:'Лист ожидания',rejected:'Отклонена',cancelled:'Отменена',queued:'В очереди',sending:'Отправляется',sent:'Отправлено',failed:'Ошибка'}
const statusLabel=(value:string)=>statusNames[value]||value
const roleNames:Record<string,string>={admin:'Администратор',manager:'Менеджер',editor:'Редактор',analyst:'Аналитик',scanner:'Контроль входа'}
const initials=(name:string)=>name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()
const tabs=[{id:'overview',name:'Обзор',permission:'analytics'},{id:'registrations',name:'Заявки',permission:'registrations.read'},{id:'content',name:'Контент',permission:'content'},{id:'settings',name:'Настройки',permission:'settings'},{id:'templates',name:'Шаблоны писем',permission:'templates'},{id:'mail',name:'Очередь писем',permission:'mail'},{id:'analytics',name:'Аналитика',permission:'analytics'},{id:'audit',name:'Журнал',permission:'audit'},{id:'roles',name:'Доступ',permission:'roles'},{id:'checkin',name:'Проход',permission:'checkin'},{id:'retention',name:'Хранение данных',permission:'retention'}]
const tabOrder=['overview','registrations','analytics','content','templates','mail','settings','checkin','audit','roles','retention']
tabs.sort((a,b)=>tabOrder.indexOf(a.id)-tabOrder.indexOf(b.id))
const textLabels:Record<string,string>={heroTitle:'Название мероприятия',heroDate:'Дата мероприятия',heroTime:'Время мероприятия',heroVenue:'Площадка мероприятия',heroDescription:'Описание первого экрана',aboutHeading:'Заголовок о мероприятии',aboutText:'Текст о мероприятии',forbesLabel:'Подпись партнёра',forbesTitle:'Заголовок партнёрского блока',programTitle:'Заголовок программы',speakersTitle:'Заголовок спикеров',tedTitle:'Название первой группы спикеров',discussionTitle:'Название дискуссии',registrationTitle:'Заголовок регистрации',registrationDescription:'Описание регистрации',contactTitle:'Заголовок контактов',contactEmail:'Контактный email',contactPhone:'Контактный телефон',routeLabel:'Подпись маршрута',routeTitle:'Заголовок маршрута',address:'Адрес площадки',routeWalk:'Маршрут пешком',routeCar:'Маршрут на машине',faqTitle:'Заголовок FAQ',footerEvent:'Дата и площадка в подвале'}
const textGroups=[
 {id:'hero',title:'Первый экран',description:'Главная информация, которую гости видят при открытии сайта.',keys:['heroTitle','heroDate','heroTime','heroVenue','heroDescription']},
 {id:'about',title:'О мероприятии',description:'Заголовок и описание события.',keys:['aboutHeading','aboutText']},
 {id:'partner',title:'Партнёр',description:'Подпись и текст блока Forbes.',keys:['forbesLabel','forbesTitle']},
 {id:'program',title:'Программа и спикеры',description:'Названия разделов и групп выступлений.',keys:['programTitle','speakersTitle','tedTitle','discussionTitle']},
 {id:'registration',title:'Регистрация',description:'Заголовок и описание формы для гостей.',keys:['registrationTitle','registrationDescription']},
 {id:'contacts',title:'Контакты',description:'Email и телефон обновляются в форме и в подвале сайта.',keys:['contactTitle','contactEmail','contactPhone']},
 {id:'route',title:'Как добраться',description:'Адрес площадки и инструкции для гостей.',keys:['routeLabel','routeTitle','address','routeWalk','routeCar']},
 {id:'footer',title:'FAQ и футер',description:'Заголовок вопросов и информация в нижней части сайта.',keys:['faqTitle','footerEvent']},
]
const currentTextGroup=computed(()=>textGroups.find(g=>g.id===textGroup.value)||textGroups[0])
const shortTextFields=new Set(['heroDate','heroTime','heroVenue','forbesLabel','programTitle','speakersTitle','tedTitle','discussionTitle','contactEmail','contactPhone','routeLabel'])
const fieldLabels:Record<string,string>={title:'Название',time:'Время',name:'Имя и фамилия',role:'Должность',topic:'Тема выступления',question:'Вопрос',answer:'Ответ'}
const activeTitle=computed(()=>tabs.find(x=>x.id===tab.value)?.name||'Панель управления')
const can=(p:string)=>me.value?.permissions?.includes(p)
const send=(path:string,data:unknown,method='POST')=>request(path,{method,body:JSON.stringify(data)})
const filters=()=>new URLSearchParams({q:tab.value==='registrations'?q.value:'',status:status.value,utm_source:source.value,utm_campaign:campaign.value,page:String(page.value)}).toString()
async function work(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'Не удалось выполнить действие'}finally{busy.value=false}}
async function load(){
 if(tab.value==='overview')overview.value=await request('admin/overview')
 else if(tab.value==='registrations'){const result=await request('admin/registrations?'+filters());rows.value=result.rows;total.value=result.total}
 else if(tab.value==='content'){const result=await request('admin/content');initialized.value=!!result.content;content.value=result.content||initialContent();contentVersion.value=result.version}
 else if(tab.value==='settings'){config.value=await request('admin/settings');initialized.value=config.value.version>0}
 else if(tab.value==='templates')templates.value=await request('admin/templates')
 else if(tab.value==='analytics')stats.value=await request('admin/analytics?'+filters())
 else if(tab.value==='roles')roles.value=await request('admin/roles')
 else if(tab.value==='mail'||tab.value==='audit')rows.value=await request('admin/'+tab.value)
}
async function choose(id:string){if(busy.value)return;tab.value=id;menuOpen.value=false;history.replaceState(null,'','/admin?tab='+encodeURIComponent(id));rows.value=[];page.value=0;await work(load)}
async function initialize(){await work(async()=>{await send('admin/initialize',{content:initialContent()});initialized.value=true;await load();notice.value='База инициализирована. Приём закрыт до утверждения настроек.'})}
async function update(row:Data,action:string){await work(async()=>{await send(`admin/registrations/${row.id}/${action}`,{version:row.version});await load();notice.value='Сохранено'})}
async function saveConfig(){await work(async()=>{await send('admin/settings',config.value,'PUT');await load();notice.value='Настройки сохранены'})}
async function saveContent(){await work(async()=>{const r=await send('admin/content',{content:content.value,version:contentVersion.value},'PUT');contentVersion.value=r.version;notice.value='Черновик сохранён'})}
async function publish(){await work(async()=>{const r=await send('admin/content/publish',{version:contentVersion.value});contentVersion.value=r.version;notice.value='Опубликовано на сайте'})}
async function saveTemplate(t:Data){await work(async()=>{await send('admin/templates',t,'PUT');await load();notice.value='Шаблон сохранён; уже созданные задания сохраняют прежний текст'})}
async function testTemplate(t:Data,sendMail=false){await work(async()=>{preview.value=await send('admin/templates/test',{id:t.id,send:sendMail});notice.value=sendMail?'Тестовое письмо поставлено в очередь на ваш email':'Предпросмотр шаблона готов'})}
async function dispatch(){await work(async()=>{const r=await send('admin/mail/run',{});await load();notice.value=r.disabled?'Отправка отключена. Нужны провайдер, отправитель и включение в настройках.':`Обработано заданий: ${r.processed}`})}
async function exportCsv(){await work(async()=>{const response=await fetch('/api/admin/export?'+filters());if(!response.ok){const r=await response.json();throw Error(r.error)}const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download='registrations.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value='Экспорт готов'})}
async function uploadPhoto(event:Event,item:Data){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await work(async()=>{const response=await fetch('/api/admin/media',{method:'POST',headers:{'Content-Type':file.type},body:file});const r=await response.json();if(!response.ok)throw Error(r.error);item.image=r.path;notice.value='Фото загружено. Сохраните черновик и опубликуйте.'})}
async function revokeRole(value:string){await work(async()=>{await send('admin/roles',{principal:value},'DELETE');await load();notice.value='Роль отозвана'})}
async function saveRole(){await work(async()=>{await send('admin/roles',{principal:principal.value,role:role.value},'PUT');await load();notice.value='Роль сохранена'})}
async function retentionRun(confirm=false){await work(async()=>{retention.value=await send('admin/retention',{confirm});notice.value=confirm?'Удаление завершено':'Проверьте количество записей перед удалением'})}
const scanId=ref(''),scanVersion=ref(1)
async function checkin(){await work(async()=>{await send(`admin/registrations/${scanId.value}/checkin`,{version:scanVersion.value});notice.value='Проход отмечен';scanVersion.value++})}
function add(kind:string){const items:Record<string,Data>={program:{title:'',time:'18:30'},speakers:{id:Date.now(),name:'',role:'',topic:'',image:'/assets/speaker.webp'},faq:{question:'',answer:''}};content.value[kind].push(items[kind])}
function move(kind:string,i:number,delta:number){const arr=content.value[kind];if(i+delta<0||i+delta>=arr.length)return;const [item]=arr.splice(i,1);arr.splice(i+delta,0,item)}
onMounted(()=>work(async()=>{me.value=await request('admin/me');const requested=new URLSearchParams(location.search).get('tab');tab.value=tabs.find(t=>t.id===requested&&can(t.permission))?.id||tabs.find(t=>can(t.permission))?.id||'none';await load()}))
</script>
<template>
 <div class="admin-shell">
  <header class="admin-topbar"><a href="/" class="admin-brand"><span class="admin-brand-mark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" aria-hidden="true"><path d="m13 2-9 12h7l-1 8 10-13h-7z"/></svg></span><span><strong>ТУРБО.РЕЙВ</strong><small>Панель управления</small></span></a><h1 class="visually-hidden">Управление мероприятием</h1><div class="topbar-actions"><a href="/" class="back-to-site">Открыть сайт ↗</a><button class="icon-button mobile-menu-button" :aria-expanded="menuOpen" aria-controls="admin-navigation" aria-label="Меню управления" @click="menuOpen=!menuOpen"><AdminIcon name="overview"/></button><button v-if="me&&can('settings')" class="icon-button" aria-label="Настройки мероприятия" @click="choose('settings')"><AdminIcon name="settings"/></button><span v-if="me" class="account-avatar" :title="me.email">{{me.email[0].toUpperCase()}}</span></div></header>
  <p v-if="!me&&!busy">Для входа нужен доступ организатора. <a href="/signin-with-chatgpt?return_to=/admin" target="_top">Войти через ChatGPT</a></p>
  <div v-if="me" class="admin-layout"><aside class="admin-sidebar" :class="{'is-open':menuOpen}"><nav id="admin-navigation" aria-label="Разделы управления"><button v-for="t in tabs.filter(t=>can(t.permission)&&!['audit','roles','retention'].includes(t.id))" :key="t.id" :disabled="busy" :aria-current="tab===t.id?'page':undefined" @click="choose(t.id)"><AdminIcon :name="t.id"/><span>{{t.name}}</span><span v-if="t.id==='registrations'&&overview.pending" class="nav-count" aria-hidden="true">{{overview.pending}}</span></button></nav><div class="sidebar-bottom"><p class="sidebar-heading">СИСТЕМА</p><div class="system-links"><button v-for="t in tabs.filter(t=>can(t.permission)&&['audit','roles','retention'].includes(t.id))" :key="t.id" :disabled="busy" :aria-current="tab===t.id?'page':undefined" @click="choose(t.id)">{{t.name==='Хранение данных'?'Данные':t.name}}</button></div><div class="sidebar-account"><span class="account-avatar">{{me.email[0].toUpperCase()}}</span><span><strong>{{roleNames[me.role]||me.role}}</strong><small>{{me.email}}</small></span></div></div></aside><div class="admin-workspace"><div v-if="tab!=='overview'" class="page-context"><span>Панель управления</span><span>/</span><strong>{{activeTitle}}</strong></div>
  <p v-if="busy" role="status" aria-live="polite">Загрузка…</p><p v-if="error" role="alert" class="error">{{error}} <button @click="work(load)">Повторить</button></p><p v-if="notice" role="status" class="notice">{{notice}}</p>
  <button v-if="me&&can('settings')&&!initialized" :disabled="busy" @click="initialize">Инициализировать настройки и текущий контент</button>
  <main :aria-busy="busy">
   <section v-if="tab==='overview'" class="overview-section"><div class="section-heading"><div><h2>Обзор мероприятия</h2><p>Все показатели в одном месте</p></div><button class="icon-button refresh-button" :disabled="busy" aria-label="Обновить показатели" @click="work(load)"><AdminIcon name="refresh"/></button></div><div class="metric-grid"><article class="metric-card"><span>Регистрации</span><strong>{{overview.total??'—'}}</strong><small>+{{overview.today||0}} сегодня</small></article><article class="metric-card"><span>Ожидают</span><strong>{{overview.pending??'—'}}</strong><small>Требуют решения</small></article><article class="metric-card"><span>Подтверждено</span><strong>{{overview.approved??'—'}}</strong><small>{{overview.total?Math.round(overview.approved/overview.total*100):0}}% заявок</small></article><article class="metric-card"><span>Письма</span><strong>{{overview.sent??'—'}}</strong><small>Отправлены гостям</small></article></div><article v-if="can('registrations.read')" class="recent-card"><div class="card-heading"><h3>Последние заявки</h3><button class="text-button" @click="choose('registrations')">Все заявки →</button></div><div v-for="guest in overview.latest" :key="guest.id" class="recent-guest"><span class="guest-avatar">{{initials(guest.data.name+' '+guest.data.surname)}}</span><div class="guest-identity"><strong>{{guest.data.name}} {{guest.data.surname}}</strong><small>{{guest.data.company}}</small></div><span class="status-badge" :class="'status-'+guest.status">{{statusLabel(guest.status)}}</span></div><div v-if="!busy&&!overview.latest?.length" class="empty-state"><AdminIcon name="registrations"/><h3>Пока нет заявок</h3><p>Новые гости появятся здесь после регистрации.</p></div></article><div v-if="overview.mode==='closed'" class="mode-notice"><span class="mode-dot"></span><div><strong>Приём заявок закрыт</strong><p>Откройте регистрацию в настройках, когда всё будет готово.</p></div><button v-if="can('settings')" class="text-button" @click="choose('settings')">Настроить →</button></div></section>
   <section v-if="tab==='registrations'||tab==='analytics'">
    <h2>{{tab==='analytics'?'Аналитика по данным БД':'Заявки'}}</h2>
    <form class="filters" @submit.prevent="page=0;work(load)"><label v-if="tab==='registrations'">Поиск<input v-model="q" placeholder="Имя, компания, email"></label><label>Статус<select v-model="status"><option value="">Все</option><option v-for="s in ['pending','approved','waitlisted','rejected','cancelled']" :key="s" :value="s">{{statusLabel(s)}}</option></select></label><label>UTM source<input v-model="source"></label><label>UTM campaign<input v-model="campaign"></label><button :disabled="busy">Применить</button></form>
    <template v-if="tab==='registrations'"><p>Найдено: {{total}}</p><button v-if="can('export')" :disabled="busy" @click="exportCsv">Экспорт разрешённых полей CSV</button><div class="table-wrap"><table><caption>Список заявок</caption><thead><tr><th>Гость</th><th>Контакт</th><th>Статус</th><th>Источник</th><th>Действия</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.data.surname}} {{row.data.name}}<br>{{row.data.company}} · {{row.data.position}}</td><td>{{row.email}}<br>{{row.data.phone}}</td><td><span class="status-badge" :class="'status-'+row.status">{{statusLabel(row.status)}}</span><br><small>{{new Date(row.created_at).toLocaleDateString('ru-RU')}}</small></td><td>{{row.utm.utm_source||'—'}}<br>{{row.utm.utm_campaign||'—'}}</td><td><template v-if="can('registrations.write')"><button v-if="['pending','waitlisted'].includes(row.status)" :disabled="busy" class="approve-action" @click="update(row,'approve')">Одобрить</button><button v-if="['pending','waitlisted','approved'].includes(row.status)" :disabled="busy" class="reject-action" @click="update(row,'reject')">Отклонить</button><button v-if="!['cancelled','rejected'].includes(row.status)" :disabled="busy" @click="update(row,'cancel')">Отменить</button></template><code>{{row.id}}</code></td></tr></tbody></table></div><p v-if="!busy&&!rows.length">Заявок по выбранному фильтру нет.</p><div class="actions"><button :disabled="busy||page===0" @click="page--;work(load)">Назад</button><span>Страница {{page+1}}</span><button :disabled="busy||(page+1)*50>=total" @click="page++;work(load)">Далее</button></div></template>
    <template v-else><h3>Статусы</h3><p v-if="!stats.statuses?.length">Данных пока нет.</p><ul><li v-for="s in stats.statuses" :key="s.status">{{s.status}}: {{s.count}}</li></ul><h3>Источники</h3><ul><li v-for="s in stats.sources" :key="s.source">{{s.source||'Без UTM'}}: {{s.count}}</li></ul><p>Прошли на площадку: {{stats.checkedIn||0}}</p></template>
   </section>
   <section v-if="tab==='settings'"><h2>Настройки регистрации</h2><p>open — автоматическое подтверждение; moderated — решение менеджера; waitlist — лист ожидания; closed — приём закрыт. При полном зале open возвращает отказ без создания заявки. Отмена освобождает место, автоматического продвижения из листа ожидания нет.</p><form @submit.prevent="saveConfig"><label>Режим<select v-model="config.mode"><option v-for="m in ['open','moderated','waitlist','closed']" :key="m">{{m}}</option></select></label><label>Вместимость<input v-model.number="config.capacity" type="number" min="0" max="100000" required></label><label>Лимит всех заявок (пусто — без лимита)<input :value="config.maxApplications??''" type="number" min="1" @input="config.maxApplications=($event.target as HTMLInputElement).value?Number(($event.target as HTMLInputElement).value):null"></label><label>Срок хранения, дней (пусто — не утверждён)<input :value="config.retentionDays??''" type="number" min="1" @input="config.retentionDays=($event.target as HTMLInputElement).value?Number(($event.target as HTMLInputElement).value):null"></label><label><input v-model="config.rejectionMail" type="checkbox">Письма об отказе</label><label><input v-model="config.mailEnabled" type="checkbox">Разрешить отправку писем</label><label><input v-model="config.checkIn" type="checkbox">Учитывать фактический проход</label><h3>Согласия</h3><p>При изменении текста обязательно измените версию. Принятый текст и версия сохраняются в заявке.</p><label>Версия обязательного согласия<input v-model="config.consentVersion" required></label><label>Точный текст обязательного согласия<textarea v-model="config.consentText" required rows="5"></textarea></label><label>Версия согласия на рассылку<input v-model="config.marketingVersion" required></label><label>Точный текст согласия на рассылку<textarea v-model="config.marketingText" required rows="5"></textarea></label><label>Правовое основание обязательного согласия<textarea v-model="config.consentBasis" rows="3"></textarea></label><label>Правовое основание рассылки<textarea v-model="config.marketingBasis" rows="3"></textarea></label><label><input v-model="config.legalApproved" type="checkbox">Тексты и правовые основания проверены и утверждены организатором</label><label>Разрешённые поля экспорта (выберите несколько)<select v-model="config.exportFields" multiple size="8"><option v-for="f in ['surname','name','company','position','email','phone','status','created_at','utm_source','utm_medium','utm_campaign','checked_in_at']" :key="f">{{f}}</option></select></label><button :disabled="busy">Сохранить настройки</button></form></section>
   <section v-if="tab==='content'"><h2>Контент сайта</h2><p>Сначала сохраните черновик, затем проверьте предпросмотр и опубликуйте.</p><div class="actions content-toolbar"><button :disabled="busy||!initialized" @click="saveContent">Сохранить черновик</button><a href="/?preview=1" target="_blank" rel="noopener">Предпросмотр сохранённого черновика ↗</a><button :disabled="busy||!initialized" @click="publish">Опубликовать</button></div><div class="content-sections" role="group" aria-label="Разделы контента"><button v-for="section in [{id:'texts',label:'Текстовые блоки'},{id:'program',label:'Программа'},{id:'speakers',label:'Спикеры'},{id:'faq',label:'FAQ'}]" :key="section.id" :aria-pressed="contentPanel===section.id" @click="contentPanel=section.id">{{section.label}}</button></div><div v-if="contentPanel==='texts'" class="text-editor-layout"><nav class="text-group-nav" aria-label="Блоки сайта"><button v-for="group in textGroups" :key="group.id" :aria-current="textGroup===group.id?'page':undefined" @click="textGroup=group.id"><span>{{group.title}}</span><small aria-hidden="true">{{group.keys.length}}</small></button></nav><article class="text-editor-card"><div class="editor-card-heading"><span class="editor-eyebrow">ТЕКСТОВЫЙ БЛОК</span><h3>{{currentTextGroup.title}}</h3><p>{{currentTextGroup.description}}</p></div><div class="text-editor-fields"><label v-for="key in currentTextGroup.keys" :key="key" :class="{'short-field':shortTextFields.has(key)}">{{textLabels[key]||key}}<input v-if="shortTextFields.has(key)" v-model="content.texts[key]" :type="key==='contactEmail'?'email':key==='contactPhone'?'tel':'text'"><textarea v-else v-model="content.texts[key]" :rows="['aboutText','heroDescription','registrationDescription','routeCar','routeWalk'].includes(key)?5:3"></textarea></label></div></article></div><template v-for="kind in contentPanel==='texts'?[]:[contentPanel]" :key="kind"><h3>{{({program:'Программа',speakers:'Спикеры',faq:'FAQ'} as Data)[kind]}}</h3><fieldset v-for="(item,i) in content[kind]" :key="i"><legend>{{Number(i)+1}}</legend><img v-if="kind==='speakers'" :src="item.image" class="speaker-preview" :alt="item.name||'Фотография спикера'"><label v-if="kind==='speakers'">Загрузить фото (PNG/JPEG/WebP, до 5 МБ)<input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadPhoto($event,item)"></label><label v-for="key in Object.keys(item).filter(k=>k!=='id'&&k!=='image')" :key="key">{{fieldLabels[key]||key}}<textarea v-if="['topic','answer'].includes(key)" v-model="item[key]" rows="4"></textarea><input v-else v-model="item[key]" :type="key==='time'?'time':'text'"></label><div class="actions"><button type="button" @click="move(kind,Number(i),-1)">Выше</button><button type="button" @click="move(kind,Number(i),1)">Ниже</button><button type="button" @click="content[kind].splice(Number(i),1)">Удалить</button></div></fieldset><button @click="add(kind)">Добавить</button></template></section>
   <section v-if="tab==='templates'"><h2>Шаблоны писем</h2><p>Переменные: <code v-pre>{{name}}, {{status}}, {{event_url}}, {{cancel_url}}</code>. Письма — текстовые. Тестовая отправка доступна администратору только на его email.</p><fieldset v-for="t in templates" :key="t.id"><legend>{{t.id}}</legend><label>Тема<input v-model="t.subject" maxlength="200"></label><label>Текст<textarea v-model="t.body" rows="7"></textarea></label><div class="actions"><button :disabled="busy" @click="saveTemplate(t)">Сохранить</button><button :disabled="busy" @click="testTemplate(t)">Проверить сохранённый шаблон</button><button v-if="can('mail')" :disabled="busy" @click="testTemplate(t,true)">Тест себе</button></div></fieldset><article v-if="preview"><h3>{{preview.subject}}</h3><pre>{{preview.body}}</pre></article><p v-if="!busy&&!templates.length">Шаблоны ещё не инициализированы.</p></section>
   <section v-if="tab==='mail'"><h2>Очередь писем</h2><button :disabled="busy" @click="dispatch">Обработать очередь</button><p>Отправка включается в настройках после подключения провайдера. Неоднозначные отправки старше 23 часов требуют сверки у провайдера.</p><div class="table-wrap"><table><thead><tr><th>Задание</th><th>Состояние</th><th>Попытки</th><th>Ошибка</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.id}}<br>{{({registered:'Получение заявки',approved:'Подтверждение участия',rejected:'Отказ',test:'Тестовое письмо'} as Data)[r.kind]||r.kind}}</td><td><span class="status-badge" :class="'status-'+r.state">{{statusLabel(r.state)}}</span></td><td>{{r.attempts}}</td><td>{{r.last_error||'—'}}</td></tr></tbody></table></div><p v-if="!busy&&!rows.length">Очередь пуста.</p></section>
   <section v-if="tab==='audit'"><h2>Журнал действий</h2><div class="table-wrap"><table><thead><tr><th>Время</th><th>Кто</th><th>Действие</th><th>Объект</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.created_at}}</td><td>{{r.actor}}</td><td>{{r.action}}</td><td>{{r.resource}}</td></tr></tbody></table></div><p v-if="!busy&&!rows.length">Журнал пуст.</p></section>
   <section v-if="tab==='roles'"><h2>Доступ сотрудников</h2><p>Роли проверяет сервер. Перед назначением роли сотруднику ему также нужен доступ к самому приватному сайту. Первоначальный администратор задаётся в серверной переменной BOOTSTRAP_ADMIN_EMAILS.</p><form @submit.prevent="saveRole"><label>Email или ID сотрудника<input v-model="principal" required></label><label>Роль<select v-model="role"><option v-for="r in ['admin','manager','editor','analyst','scanner']" :key="r">{{r}}</option></select></label><button :disabled="busy">Назначить</button></form><ul><li v-for="r in roles" :key="r.principal">{{r.principal}} — {{r.role}} <button :disabled="busy" @click="revokeRole(r.principal)">Отозвать</button></li></ul><p v-if="!roles.length">Явные роли ещё не назначены.</p></section>
   <section v-if="tab==='checkin'"><h2>Отметка прохода</h2><p>Доступна только для одобренных заявок при включённом учёте прохода. Менеджер передаёт ID и текущую версию заявки.</p><form @submit.prevent="checkin"><label>ID заявки<input v-model="scanId" required></label><label>Версия<input v-model.number="scanVersion" type="number" min="1" required></label><button :disabled="busy">Отметить проход</button></form></section>
   <section v-if="tab==='retention'"><h2>Хранение персональных данных</h2><a href="/api/admin/backup" download="turbo-rave-backup.json">Скачать резервную копию БД</a><p>Удаление доступно после утверждения срока хранения. Сначала покажите количество. Заявки с отправляющимися письмами пропускаются. Резервные копии требуют отдельного удаления по тому же регламенту.</p><button :disabled="busy" @click="retentionRun()">Проверить срок хранения</button><p v-if="retention">{{retention.eligible!==undefined?'Подлежат удалению: '+retention.eligible:'Удалено: '+retention.deleted}}</p><button v-if="retention?.eligible>0" :disabled="busy" @click="retentionRun(true)">Безвозвратно удалить просроченные заявки</button></section>
  </main>
 </div></div>
 </div>
</template>
